import { plainDate, plainDateToString } from '@absoluteui/core';
import { DateRangePicker, type DateRangePickerChangeDetail } from '@absoluteui/components/date-range-picker';

const host = document.createElement('div');
document.body.append(host);
DateRangePicker.create(host, {
  label: 'Stay',
  startLabel: 'Check-in',
  endLabel: 'Check-out',
  name: 'stay',
  required: true,
  min: plainDate(2026, 1, 1),
  minDays: 2,
  maxDays: 14,
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<DateRangePickerChangeDetail>).detail;
  host.dataset.value = value ? `${plainDateToString(value.start)}/${plainDateToString(value.end)}` : '';
});

import { dayOfWeek, plainDate } from '@absoluteui/core';
import { DateRangePicker } from '@absoluteui/components/date-range-picker';

const host = document.createElement('div');
document.body.append(host);
DateRangePicker.create(host, {
  label: 'Leave',
  value: { start: plainDate(2026, 10, 5), end: plainDate(2026, 10, 9) },
  startName: 'leaveFrom',
  endName: 'leaveTo',
  months: 1,
  firstDayOfWeek: 1,
  isDateDisabled: (date) => dayOfWeek(date) >= 6,
  validate: (range) => (range && range.start.month !== range.end.month ? 'Request leave within one month.' : null),
});
